// model_settings.h -- single source of truth for the firmware side.
//
// Class labels, input shape, sample rate and the tensor arena size all live
// here. Nothing else under firmware/ may hardcode a label string or an array
// size; include this instead.
//
// GENERATED by scripts/quantize.py from scripts/config.py. Edit config.py and
// re-run the pipeline rather than editing this file, so the Python and C++
// label lists cannot drift apart.

#ifndef MODEL_SETTINGS_H_
#define MODEL_SETTINGS_H_

// --- Audio capture (audio_provider) --------------------------------------
constexpr int kAudioSampleRate = 16000;
constexpr int kClipDurationMs = 1000;
constexpr int kClipSamples = kAudioSampleRate * kClipDurationMs / 1000;

// --- MFCC features (feature_provider) ------------------------------------
constexpr int kWindowSizeMs = 40;
constexpr int kWindowStrideMs = 20;
constexpr int kFeatureFrames = 49;   // 1 + (1000 - 40) / 20
constexpr int kFeatureCount = 10;    // MFCC coefficients per frame
constexpr int kFeatureElements = kFeatureFrames * kFeatureCount;

// --- Model ----------------------------------------------------------------
constexpr int kCategoryCount = 5;
constexpr int kBackgroundIndex = 0;  // the rejection class
extern const char* kCategoryLabels[kCategoryCount];

// Softmax score (0..255 in the int8 output domain, rescaled) required before
// command_responder fires the physical action.
constexpr float kDetectionThreshold = 0.80f;

// Scratch memory for the TFLM interpreter. Bump if AllocateTensors() fails;
// shrink if the sketch runs out of RAM.
constexpr int kTensorArenaSize = 30 * 1024;

#endif  // MODEL_SETTINGS_H_
